using System.Globalization;using System.Text.RegularExpressions;using System.Diagnostics;using Microsoft.EntityFrameworkCore;
namespace Decont;
public record OcrField(string? Value,int Page,string Evidence,string State="ReviewRequired",decimal? Confidence=null);
public record OcrTax(decimal Rate,decimal Base,decimal Vat,int Page,string Evidence);
public record OcrPage(int Number,string Text);
public record OcrCandidate(Guid Id,int[] Pages,Dictionary<string,OcrField> Fields,List<OcrTax> Taxes,List<string> Warnings);
public record OcrResult(string Provider,string State,string Text,List<OcrPage> Pages,List<OcrCandidate> Candidates);
public interface IDocumentExtractor {Task<OcrResult> Extract(byte[] bytes,string name,string mime,string? companyCui,CancellationToken ct);}
public static class ReceiptParser {
 static readonly Regex Amounts=new(@"(?<![\d])[-+]?\d[\d., ]*[.,]\d{2}(?!\d)",RegexOptions.Compiled);
 public static decimal? Number(string text){var s=text.Trim().Replace(" ","");var comma=s.LastIndexOf(',');var dot=s.LastIndexOf('.');if(comma>dot)s=s.Replace(".","").Replace(',','.');else s=s.Replace(",","");return decimal.TryParse(s,NumberStyles.AllowDecimalPoint|NumberStyles.AllowLeadingSign,CultureInfo.InvariantCulture,out var n)?n:null;}
 public static OcrResult Parse(List<OcrPage> pages,string? companyCui){List<OcrCandidate> candidates=[];foreach(var page in pages){var segments=Regex.Split(page.Text,@"(?im)(?=^\s*(?:BON\s+FISCAL|FACTUR[ĂA]\s+(?:FISCAL[ĂA]|NR)|INVOICE\s+(?:NO|NUMBER))\b)").Where(x=>!string.IsNullOrWhiteSpace(x)).ToList();foreach(var text in segments){if(segments.Count>1&&!Regex.IsMatch(text,@"(?i)TOTAL|FACTUR|INVOICE|BON\s+FISCAL"))continue;Dictionary<string,OcrField> fields=[];List<OcrTax> taxes=[];List<string> warnings=[];void Put(string key,string? value,string evidence){if(!string.IsNullOrWhiteSpace(value))fields[key]=new(value,page.Number,evidence);}
 var lines=text.Split('\n').Select(x=>x.Trim()).Where(x=>x!="").ToList();var date=Regex.Match(text,@"\b(\d{2}[./-]\d{2}[./-]\d{4}|\d{4}-\d{2}-\d{2})\b");if(date.Success&&DateOnly.TryParseExact(date.Value,new[]{"dd.MM.yyyy","dd/MM/yyyy","dd-MM-yyyy","yyyy-MM-dd"},CultureInfo.InvariantCulture,DateTimeStyles.None,out var day))Put("date",day.ToString("yyyy-MM-dd"),date.Value);
 var cui=Regex.Matches(text,@"(?i)\b(?:CUI|CIF|COD\s+FISCAL|VAT\s*(?:ID|NO))\s*[:#-]?\s*(RO\s*)?(\d{2,10})\b").Select(m=>Rules.Cui(m.Groups[2].Value)).Distinct().ToList();var company=Rules.Cui(companyCui);if(company!=""&&cui.Contains(company))Put("hasCompanyCui","true","CUI "+company);var supplier=cui.FirstOrDefault(x=>x!=company&&Rules.ValidCui(x));if(supplier!=null){Put("cui",supplier,"CUI "+supplier);Put("country","RO","CUI "+supplier);}if(company!=""&&!cui.Contains(company)&&cui.Count>0)warnings.Add("CUI-ul companiei nu a fost detectat; confirmă pe original. / Company VAT ID was not detected; check the original.");
 var invoice=Regex.Match(text,@"(?im)(?:FACTUR[ĂA](?:\s+FISCAL[ĂA])?|INVOICE|BON(?:\s+FISCAL)?|DOCUMENT)\s*(?:NR\.?|NO\.?|NUMBER|#)\s*[:#-]?\s*([A-Z0-9/-]+)");if(invoice.Success)Put("invoice",invoice.Groups[1].Value,invoice.Value);
 var currency=Regex.Match(text,@"\b(RON|LEI|EUR|USD|GBP|CHF|HUF|PLN|CZK)\b",RegexOptions.IgnoreCase);if(currency.Success)Put("currency",currency.Value.ToUpperInvariant()=="LEI"?"RON":currency.Value.ToUpperInvariant(),currency.Value);
 var totalLine=lines.LastOrDefault(l=>Regex.IsMatch(l,@"(?i)\b(?:TOTAL\s*(?:DE\s*PLAT[ĂA]|GENERAL|AMOUNT|DUE|DE\s*ACHITAT)?|AMOUNT\s+DUE|GRAND\s+TOTAL)\b")&&!Regex.IsMatch(l,@"(?i)SUBTOTAL|SUB-TOTAL|TOTAL\s*(?:TVA|TAX|VAT|BAZ[ĂA])"));if(totalLine!=null){var amounts=Amounts.Matches(totalLine);if(amounts.Count>0&&Number(amounts[^1].Value) is decimal total)Put("amount",total.ToString("0.00",CultureInfo.InvariantCulture),totalLine);}
 foreach(var line in lines){var rate=Regex.Match(line,@"(?<!\d)(\d{1,2}(?:[.,]\d+)?)\s*%");if(!rate.Success)continue;var pct=Number(rate.Groups[1].Value);if(pct==null)continue;var numbers=Amounts.Matches(line[(rate.Index+rate.Length)..]).Select(m=>Number(m.Value)).Where(n=>n!=null).Select(n=>n!.Value).ToList();if(numbers.Count>=2)taxes.Add(new(pct.Value,numbers[0],numbers[1],page.Number,line));else if(numbers.Count==1&&pct==0)taxes.Add(new(0,numbers[0],0,page.Number,line));else if(numbers.Count==1&&Regex.IsMatch(line,@"(?i)TVA|VAT|TAX")){var paid=numbers[0];taxes.Add(new(pct.Value,Rules.Money(paid*100/pct.Value),paid,page.Number,line));warnings.Add("Baza TVA a fost dedusă din TVA; verifică baza exactă de pe document. / VAT base was derived; verify the exact printed base.");}}
 var name=lines.FirstOrDefault(l=>l.Length>=3&&!Regex.IsMatch(l,@"(?i)BON\s+FISCAL|FACTURA|INVOICE|CUI|CIF|TOTAL|\d{2}[./]\d{2}[./]\d{4}"));Put("supplier",name,name??"");if(taxes.Select(t=>t.Rate).Distinct().Count()!=taxes.Count)warnings.Add("Mai multe valori pentru aceeași cotă; verifică și cumulează baza/TVA. / Multiple entries for one rate; verify and aggregate.");warnings.Add("Propuneri OCR: verifică toate valorile pe original. / OCR suggestions: verify all values against the original.");if(fields.Count>0||taxes.Count>0)candidates.Add(new(Guid.NewGuid(),[page.Number],fields,taxes,warnings));}}
 return new("Tesseract",candidates.Count>0?"ReviewRequired":"ManualEntryRequired",string.Join("\n\n",pages.Select(p=>p.Text)),pages,candidates);
 }
}
public sealed class LocalDocumentExtractor(IConfiguration config):IDocumentExtractor {
 public async Task<OcrResult> Extract(byte[] bytes,string name,string mime,string? companyCui,CancellationToken ct){var temp=Path.Combine(Path.GetTempPath(),"decont-ocr-"+Guid.NewGuid());Directory.CreateDirectory(temp);try{var input=Path.Combine(temp,"original"+Path.GetExtension(name));await File.WriteAllBytesAsync(input,bytes,ct);List<string> images=[];if(mime=="application/pdf"){await Run(config["Ocr:PdfRenderer"]??"pdftoppm",["-png","-scale-to","2400",input,Path.Combine(temp,"page")],ct);images=Directory.GetFiles(temp,"page-*.png").OrderBy(p=>int.Parse(Regex.Match(Path.GetFileNameWithoutExtension(p),@"\d+$").Value)).ToList();}else if(mime=="image/heic"){var output=Path.Combine(temp,"image.png");await Run(config["Ocr:HeicConverter"]??"heif-convert",[input,output],ct);images.Add(output);}else images.Add(input);Guard.Require(images.Count<=(config.GetValue<int?>("Ocr:MaxPages")??50),"ocr_pages","Fișierul depășește limita OCR. Completează manual sau separă documentele.","File exceeds the OCR page limit. Enter manually or separate documents.");List<OcrPage> pages=[];for(int i=0;i<images.Count;i++){var text=await Run(config["Ocr:Tesseract"]??"tesseract",[images[i],"stdout","-l",config["Ocr:Languages"]??"ron+eng"],ct);pages.Add(new(i+1,text));}return ReceiptParser.Parse(pages,companyCui);}finally{Directory.Delete(temp,true);}}
 public static async Task<string> Run(string exe,IEnumerable<string> args,CancellationToken ct){using var p=new Process();p.StartInfo=new(exe){RedirectStandardOutput=true,RedirectStandardError=true,UseShellExecute=false};foreach(var a in args)p.StartInfo.ArgumentList.Add(a);p.Start();using var limit=CancellationTokenSource.CreateLinkedTokenSource(ct);limit.CancelAfter(TimeSpan.FromMinutes(3));var stdout=p.StandardOutput.ReadToEndAsync(limit.Token);var stderr=p.StandardError.ReadToEndAsync(limit.Token);try{await p.WaitForExitAsync(limit.Token);}catch{if(!p.HasExited)p.Kill(true);throw;}await stderr;Guard.Require(p.ExitCode==0,"ocr","Extragerea a eșuat. Poți completa manual.","Extraction failed. You can enter manually.");return await stdout;}
}
public static class DocumentCapture {
 public static void Map(RouteGroupBuilder api){
  api.MapPost("/reports/{id:guid}/capture",async(Guid id,HttpContext c,Db db,Reports svc,IStore store)=>await ReceiptFiles.Upload(id,null,c,db,svc,store));
  api.MapPost("/reports/{id:guid}/documents/{document:guid}/extract",async(Guid id,Guid document,VersionRequest i,HttpContext c,Db db,Reports svc)=>await Api.Atomic(db,c,i,async()=>{var r=await svc.Version(id,i.Version,c.User);svc.Edit(r,c.User,i.Reason);IOriginalDocument? file=r.Attachments.FirstOrDefault(e=>e.Id==document&&!e.Archived)??(IOriginalDocument?)r.Lines.SelectMany(l=>l.Evidence).FirstOrDefault(e=>e.Id==document&&!e.Archived);Guard.Require(file!=null&&file.Scan=="Clean","scan","Documentul trebuie să fie verificat.","Document must be scanned.");Guard.Require(!await db.Jobs.AnyAsync(j=>j.Json==document.ToString()&&(j.Kind=="Ocr"||j.Kind=="OcrReport")&&(j.State=="Pending"||j.State=="Processing")),"pending","Extragerea este deja în curs.","Extraction is already queued.");file!.Ocr=Serialization.Write(new{state="Pending"});db.Jobs.Add(new(){Kind=file is ReportAttachment?"OcrReport":"Ocr",Json=document.ToString()});Reports.Touch(r);svc.Log(c.User,id,document.ToString(),"ExtractionRequested",reason:i.Reason);return Api.View(r);}));
 }
 public static void Link(Report r,Line line,Guid? document,Reports svc,HttpContext c){if(document==null)return;var file=r.Attachments.SingleOrDefault(e=>e.Id==document&&!e.Archived);Guard.Require(file!=null&&file.Scan=="Clean","source","Originalul OCR nu este disponibil sau verificat.","OCR original is unavailable or unscanned.");var ids=Serialization.Read<List<Guid>>(file!.CoveredLines);if(!ids.Contains(line.Id))ids.Add(line.Id);file.CoveredLines=Serialization.Write(ids);svc.Log(c.User,r.Id,line.Id.ToString(),"OcrSuggestionsReviewed",after:new{document,line.Json},reason:c.User.IsInRole("Finance")?c.Request.Headers["X-Change-Reason"].ToString():null);}
}
